{"api_file": {"path": "src/api/posRewardCatalogItemApi.ts", "content": "const BASE_URL = import.meta.env.VITE_API_URL ?? "https://smartloansbackend.azurewebsites.net";

export interface PosRewardCatalogItem {
  catalogItemId: number;
  companyId: number;
  name: string;
  rewardType: 'fixed_discount' | 'free_product' | string; // Ensure string for other potential types
  requiredPoints: number;
  discountValue: number | null;
  freeProductId: number | null;
  isActive: boolean;
  description: string | null;
  created_At: string;
  updated_at: string | null;
}

export interface PosRewardCatalogItemListResponse {
  posRewardCatalogItems: PosRewardCatalogItem[];
}

// GET ALL — POST /all_posRewardCatalogItems
export async function getAllPosRewardCatalogItems(companyId: number): Promise<PosRewardCatalogItem[]> {
  const res = await fetch(BASE_URL + "/all_posRewardCatalogItems", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "posRewardCatalogItems": [{ "companyId": companyId }] }),
  });
  if (!res.ok) {
    throw new Error(await res.text());
  }
  const data: PosRewardCatalogItemListResponse = await res.json();
  return data.posRewardCatalogItems ?? [];
}

// CREATE — action: 1
export async function createPosRewardCatalogItem(payload: Omit<PosRewardCatalogItem, "catalogItemId" | "created_At" | "updated_at">): Promise<PosRewardCatalogItem> {
  const res = await fetch(BASE_URL + "/posRewardCatalogItems", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "posRewardCatalogItems": [{ "action": 1, ...payload }] }),
  });
  if (!res.ok) {
    throw new Error(await res.text());
  }
  return await res.json();
}

// UPDATE — action: 2
export async function updatePosRewardCatalogItem(id: number, payload: Partial<Omit<PosRewardCatalogItem, "created_At" | "updated_at" | "catalogItemId" | "companyId">>): Promise<PosRewardCatalogItem> {
  const res = await fetch(BASE_URL + "/posRewardCatalogItems", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "posRewardCatalogItems": [{ "action": 2, "catalogItemId": id, ...payload }] }),
  });
  if (!res.ok) {
    throw new Error(await res.text());
  }
  return await res.json();
}

// DELETE — action: 3
export async function deletePosRewardCatalogItem(id: number, companyId: number): Promise<void> {
  const res = await fetch(BASE_URL + "/posRewardCatalogItems", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "posRewardCatalogItems": [{ "action": 3, "catalogItemId": id, "companyId": companyId }] }),
  });
  if (!res.ok) {
    throw new Error(await res.text());
  }
}
"}, "page_file": {"path": "src/pages/PosRewardCatalogItemPage.tsx", "content": "import React, { useState, useEffect, useRef } from 'react';
import {
  IonPage,
  IonContent,
  IonList,
  IonItem,
  IonLabel,
  IonNote,
  IonInput,
  IonSelect,
  IonSelectOption,
  IonModal,
  IonButton,
  IonFab,
  IonFabButton,
  IonIcon,
  IonAlert,
  IonLoading,
  IonToast,
  IonSpinner,
  IonRefresher,
  IonRefresherContent,
  IonInfiniteScroll,
  IonInfiniteScrollContent,
  IonToggle,
  IonBadge,
  IonSearchbar,
  useIonViewWillEnter,,
  InputInputEventDetail,
  RefresherEventDetail,
  SearchbarInputEventDetail,
  SelectChangeEventDetail,
  ToggleChangeEventDetail
} from '@ionic/react';
import { addOutline, pencilOutline, trashOutline, checkmark, checkmarkCircle, alertCircleOutline } from 'ionicons/icons';
import { useUser } from '../contexts/UserContext';
import Header from '../components/Header';
import AlertPopover from '../components/PopOver/AlertPopover';
import MailPopover from '../components/PopOver/MailPopover';
import {
  PosRewardCatalogItem,
  getAllPosRewardCatalogItems,
  createPosRewardCatalogItem,
  updatePosRewardCatalogItem,
  deletePosRewardCatalogItem,
} from '../api/posRewardCatalogItemApi';
import { InputInputEventDetail, SelectChangeEventDetail, ToggleChangeEventDetail, SearchbarInputEventDetail } from '@ionic/core';

const toHermosillo = (utc: string | undefined | null): string => {
  if (!utc) return '';
  const d = new Date(utc.includes('Z') ? utc : utc + 'Z');
  // Hermosillo is UTC-7
  return new Date(d.getTime() - 7 * 60 * 60 * 1000).toLocaleString();
};

interface PosRewardCatalogItemFormState {
  name: string;
  rewardType: 'fixed_discount' | 'free_product' | string;
  requiredPoints: string;
  discountValue: string;
  freeProductId: string;
  isActive: boolean;
  description: string;
}

const rewardTypeOptions = [
  { value: 'fixed_discount', label: 'Descuento Fijo' },
  { value: 'free_product', label: 'Producto Gratis' },
];

const PosRewardCatalogItemPage: React.FC = () => {
  const { companyId } = useUser();
  const [items, setItems] = useState<PosRewardCatalogItem[]>([]);
  const [filteredItems, setFilteredItems] = useState<PosRewardCatalogItem[]>([]);
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const [showModal, setShowModal] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [currentItem, setCurrentItem] = useState<PosRewardCatalogItem | null>(null);
  const [formState, setFormState] = useState<PosRewardCatalogItemFormState>({
    name: '',
    rewardType: '',
    requiredPoints: '',
    discountValue: '',
    freeProductId: '',
    isActive: true,
    description: '',
  });
  const [searchTerm, setSearchTerm] = useState('');
  const [showDeleteAlert, setShowDeleteAlert] = useState(false);
  const [itemToDelete, setItemToDelete] = useState<PosRewardCatalogItem | null>(null);
  const [showToast, setShowToast] = useState(false);
  const [toastMessage, setToastMessage] = useState('');
  const [toastColor, setToastColor] = useState<'success' | 'danger' | 'warning'>('success');

  const [popoverState, setPopoverState] = useState<{ 
    showAlertPopover: boolean; 
    showMailPopover: boolean; 
    event?: Event 
  }>({ showAlertPopover: false, showMailPopover: false });

  const presentAlertPopover = (e: React.MouseEvent) => setPopoverState({ ...popoverState, showAlertPopover: true, event: e.nativeEvent });
  const dismissAlertPopover = () => setPopoverState({ ...popoverState, showAlertPopover: false });
  const presentMailPopover = (e: React.MouseEvent) => setPopoverState({ ...popoverState, showMailPopover: true, event: e.nativeEvent });
  const dismissMailPopover = () => setPopoverState({ ...popoverState, showMailPopover: false });

  const ITEMS_PER_LOAD = 20; // For infinite scroll
  const [displayCount, setDisplayCount] = useState(ITEMS_PER_LOAD);

  const fetchItems = async () => {
    if (!companyId) {
      setError('Company ID is not available.');
      return;
    }
    setLoading(true);
    try {
      const data = await getAllPosRewardCatalogItems(companyId);
      setItems(data);
      setFilteredItems(data);
      setDisplayCount(ITEMS_PER_LOAD);
    } catch (err) {
      setError((err as Error).message || 'Error al cargar los elementos del catálogo.');
    } finally {
      setLoading(false);
    }
  };

  useIonViewWillEnter(() => {
    fetchItems();
  });

  useEffect(() => {
    const lowerCaseSearchTerm = searchTerm.toLowerCase();
    const filtered = items.filter(
      (item) =>
        item.name.toLowerCase().includes(lowerCaseSearchTerm) ||
        item.rewardType.toLowerCase().includes(lowerCaseSearchTerm) ||
        item.description?.toLowerCase().includes(lowerCaseSearchTerm)
    );
    setFilteredItems(filtered);
    setDisplayCount(ITEMS_PER_LOAD);
  }, [searchTerm, items]);

  const loadMoreItems = (event: CustomEvent<void>) => {
    setTimeout(() => {
      setDisplayCount((prevCount) => prevCount + ITEMS_PER_LOAD);
      (event.target as HTMLIonInfiniteScrollElement).complete();
    }, 500);
  };

  const handleRefresh = async (event: CustomEvent<RefresherEventDetail>) => {
    await fetchItems();
    event.detail.complete();
  };

  const openCreateModal = () => {
    setIsEditing(false);
    setCurrentItem(null);
    setFormState({
      name: '',
      rewardType: '',
      requiredPoints: '',
      discountValue: '',
      freeProductId: '',
      isActive: true,
      description: '',
    });
    setShowModal(true);
  };

  const openEditModal = (item: PosRewardCatalogItem) => {
    setIsEditing(true);
    setCurrentItem(item);
    setFormState({
      name: item.name,
      rewardType: item.rewardType,
      requiredPoints: item.requiredPoints.toFixed(2),
      discountValue: item.discountValue !== null ? item.discountValue.toFixed(2) : '',
      freeProductId: item.freeProductId !== null ? String(item.freeProductId) : '',
      isActive: item.isActive,
      description: item.description || '',
    });
    setShowModal(true);
  };

  const handleInputChange = (e: CustomEvent<InputInputEventDetail>) => {
    const { name, value } = e.target as HTMLIonInputElement;
    setFormState((prev) => ({ ...prev, [name!]: value! }));
  };

  const handleRewardTypeChange = (e: CustomEvent<SelectChangeEventDetail>) => {
    setFormState((prev) => ({
      ...prev,
      rewardType: e.detail.value!,
      // Reset conditional fields when reward type changes
      discountValue: '',
      freeProductId: '',
    }));
  };

  const handleToggleActive = (e: CustomEvent<ToggleChangeEventDetail>) => {
    setFormState((prev) => ({ ...prev, isActive: e.detail.checked }));
  };

  const validateForm = () => {
    if (!formState.name.trim()) return 'El nombre es obligatorio.';
    if (!formState.rewardType) return 'El tipo de recompensa es obligatorio.';
    const requiredPointsNum = parseFloat(formState.requiredPoints);
    if (isNaN(requiredPointsNum) || requiredPointsNum <= 0) return 'Los puntos requeridos deben ser un número positivo.';

    if (formState.rewardType === 'fixed_discount') {
      const discountValueNum = parseFloat(formState.discountValue);
      if (isNaN(discountValueNum) || discountValueNum <= 0) return 'El valor de descuento debe ser un número positivo.';
    } else if (formState.rewardType === 'free_product') {
      const freeProductIdNum = parseInt(formState.freeProductId);
      if (isNaN(freeProductIdNum) || freeProductIdNum <= 0) return 'El ID del producto gratis debe ser un número entero positivo.';
    }
    return '';
  };

  const handleSave = async () => {
    const validationError = validateForm();
    if (validationError) {
      setToastMessage(`⚠️ ${validationError}`);
      setToastColor('warning');
      setShowToast(true);
      return;
    }

    setSaving(true);
    setError('');
    try {
      const payload: Omit<PosRewardCatalogItem, "catalogItemId" | "created_At" | "updated_at"> = {
        companyId: companyId!,
        name: formState.name,
        rewardType: formState.rewardType,
        requiredPoints: parseFloat(formState.requiredPoints),
        discountValue: formState.rewardType === 'fixed_discount' ? parseFloat(formState.discountValue) : null,
        freeProductId: formState.rewardType === 'free_product' ? parseInt(formState.freeProductId) : null,
        isActive: formState.isActive,
        description: formState.description.trim() || null,
      };

      if (isEditing && currentItem) {
        await updatePosRewardCatalogItem(currentItem.catalogItemId, payload);
        setToastMessage('Elemento del catálogo actualizado con éxito.');
      } else {
        await createPosRewardCatalogItem(payload);
        setToastMessage('Elemento del catálogo creado con éxito.');
      }
      setToastColor('success');
      setShowToast(true);
      setShowModal(false);
      await fetchItems();
    } catch (err) {
      const errorMessage = (err as Error).message || 'Error al guardar el elemento del catálogo.';
      setError(errorMessage);
      setToastMessage(`❌ ${errorMessage}`);
      setToastColor('danger');
      setShowToast(true);
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = (item: PosRewardCatalogItem) => {
    setItemToDelete(item);
    setShowDeleteAlert(true);
  };

  const doDelete = async () => {
    if (itemToDelete && companyId) {
      setLoading(true);
      try {
        await deletePosRewardCatalogItem(itemToDelete.catalogItemId, companyId);
        setToastMessage('Elemento del catálogo eliminado con éxito.');
        setToastColor('success');
        setShowToast(true);
        await fetchItems();
      } catch (err) {
        const errorMessage = (err as Error).message || 'Error al eliminar el elemento del catálogo.';
        setError(errorMessage);
        setToastMessage(`❌ ${errorMessage}`);
        setToastColor('danger');
        setShowToast(true);
      } finally {
        setLoading(false);
        setItemToDelete(null);
      }
    }
  };

  return (
    <IonPage className="pos-reward-catalog-item-page">
      <Header
        presentAlertPopover={presentAlertPopover}
        presentMailPopover={presentMailPopover}
        screenTitle="Recompensas POS — POS GMO"
      />
      <AlertPopover
        isOpen={popoverState.showAlertPopover}
        event={popoverState.event}
        onDidDismiss={dismissAlertPopover}
      />
      <MailPopover
        isOpen={popoverState.showMailPopover}
        event={popoverState.event}
        onDidDismiss={dismissMailPopover}
      />

      <IonContent fullscreen className="ion-padding">
        <IonRefresher slot="fixed" onIonRefresh={handleRefresh}>
          <IonRefresherContent></IonRefresherContent>
        </IonRefresher>

        <IonSearchbar
          className="pos-reward-catalog-item-searchbar"
          value={searchTerm}
          onIonInput={(e: CustomEvent<SearchbarInputEventDetail>) => setSearchTerm(e.detail.value!)}
          placeholder="Buscar recompensas..."
        />

        {loading && items.length === 0 ? (
          <div className="ion-text-center ion-padding">
            <IonSpinner name="crescent" />
            <p>Cargando recompensas...</p>
          </div>
        ) : filteredItems.length === 0 ? (
          <div className="ion-text-center ion-padding">
            <p>No se encontraron recompensas.</p>
            <IonButton onClick={openCreateModal}>Crear Recompensa</IonButton>
          </div>
        ) : (
          <IonList className="pos-reward-catalog-item-list ion-no-padding">
            {filteredItems.slice(0, displayCount).map((item) => (
              <IonItem key={item.catalogItemId} className="pos-reward-catalog-item-item">
                <IonLabel>
                  <h2>{item.name}</h2>
                  <p>Puntos Requeridos: <strong>{item.requiredPoints.toFixed(2)}</strong></p>
                  {item.rewardType === 'fixed_discount' && item.discountValue !== null && (
                    <p>Valor de Descuento: <strong>${item.discountValue.toFixed(2)} MXN</strong></p>
                  )}
                  {item.rewardType === 'free_product' && item.freeProductId !== null && (
                    <p>ID Producto Gratis: <strong>{item.freeProductId}</strong></p>
                  )}
                  {item.description && <IonNote>{item.description}</IonNote>}
                  <p className="item-dates">
                    Creado: {toHermosillo(item.created_At)}
                    {item.updated_at && ` | Actualizado: ${toHermosillo(item.updated_at)}`}
                  </p>
                </IonLabel>
                <div slot="end" className="item-actions">
                  <IonBadge className={`reward-type-badge status-${item.rewardType.replace('_', '-')}`}>
                    {rewardTypeOptions.find(opt => opt.value === item.rewardType)?.label || item.rewardType}
                  </IonBadge>
                  <IonToggle
                    checked={item.isActive}
                    onIonChange={(e: CustomEvent<ToggleChangeEventDetail>) => {
                      // This is for display only, actual update requires an explicit action
                      // Or integrate into an immediate update function if UX requires it
                      console.log('Toggle isActive for item', item.catalogItemId, e.detail.checked);
                      // For this example, we'll assume isActive is part of the edit modal save flow
                    }}
                    aria-label={`Activar/Desactivar ${item.name}`}
                    className="pos-reward-catalog-item-toggle"
                  />
                  <IonButton fill="clear" color="medium" onClick={() => openEditModal(item)} aria-label="Editar">
                    <IonIcon icon={pencilOutline} />
                  </IonButton>
                  <IonButton fill="clear" color="danger" onClick={() => handleDelete(item)} aria-label="Eliminar">
                    <IonIcon icon={trashOutline} />
                  </IonButton>
                </div>
              </IonItem>
            ))}
          </IonList>
        )}

        <IonInfiniteScroll
          onIonInfinite={loadMoreItems}
          threshold="100px"
          disabled={displayCount >= filteredItems.length}
        >
          <IonInfiniteScrollContent loadingText="Cargando más recompensas..."></IonInfiniteScrollContent>
        </IonInfiniteScroll>

        <IonFab vertical="bottom" horizontal="end" slot="fixed">
          <IonFabButton onClick={openCreateModal} aria-label="Añadir nueva recompensa">
            <IonIcon icon={addOutline} />
          </IonFabButton>
        </IonFab>

        <IonModal isOpen={showModal} onDidDismiss={() => setShowModal(false)} className="pos-reward-catalog-item-modal">
          <Header
            screenTitle={isEditing ? 'Editar Recompensa' : 'Crear Recompensa'} 
            onClose={() => setShowModal(false)}
          />
          <IonContent className="ion-padding">
            <form onSubmit={(e) => { e.preventDefault(); handleSave(); }}>
              <div className="pos-reward-catalog-item-form-field">
                <IonInput
                  fill="outline"
                  label="Nombre *"
                  labelPlacement="floating"
                  name="name"
                  value={formState.name}
                  onIonInput={handleInputChange}
                  className={!formState.name.trim() ? 'ion-invalid ion-touched' : ''}
                  errorText={!formState.name.trim() ? 'El nombre es obligatorio' : undefined}
                />
              </div>

              <div className="pos-reward-catalog-item-form-field">
                <IonSelect
                  fill="outline"
                  label="Tipo de Recompensa *"
                  labelPlacement="floating"
                  name="rewardType"
                  value={formState.rewardType}
                  onIonChange={handleRewardTypeChange}
                  className={!formState.rewardType ? 'ion-invalid ion-touched' : ''}
                  errorText={!formState.rewardType ? 'El tipo de recompensa es obligatorio' : undefined}
                >
                  {rewardTypeOptions.map((option) => (
                    <IonSelectOption key={option.value} value={option.value}>
                      {option.label}
                    </IonSelectOption>
                  ))}
                </IonSelect>
              </div>

              <div className="pos-reward-catalog-item-form-field">
                <IonInput
                  fill="outline"
                  label="Puntos Requeridos *"
                  labelPlacement="floating"
                  name="requiredPoints"
                  type="number"
                  value={formState.requiredPoints}
                  onIonInput={handleInputChange}
